function u(t=new Date){let r=String(t.getMonth()+1).padStart(2,"0"),e=String(t.getDate()).padStart(2,"0");return`${t.getFullYear()}-${r}-${e}`}function c(t,r){let e=/^(\d{4})-(\d{2})-(\d{2})/.exec(t);if(!e)return t;let n=Number(e[1])*12+(Number(e[2])-1)+r,i=Math.floor(n/12),o=n%12+1,a=new Date(i,o,0).getDate(),s=Math.min(Number(e[3]),a);return`${i}-${String(o).padStart(2,"0")}-${String(s).padStart(2,"0")}`}function m(t,r){let e=Math.round(t*100);if(r<1||e<r)return[];let n=Math.floor(e/r);return Array.from({length:r},(i,o)=>(o<r-1?n:e-n*(r-1))/100)}function g(t=new Date){return u(t).slice(0,7)}function d(t){let[r,e]=t.split("-").map(Number);return`${t}-${String(new Date(r,e,0).getDate()).padStart(2,"0")}`}export{u as a,c as b,m as c,g as d,d as e};
